update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(1,null::text,$$Objetivo da execução penal$$,$$Define o fim da execução: efetivar o que a sentença ou a decisão criminal determinou e criar condições para a integração social do condenado e do internado. Serve de critério de leitura para os demais dispositivos da lei.$$),
(2,null,$$Jurisdição e aplicação da lei$$,$$A execução se processa perante a jurisdição penal ordinária, conforme esta lei e o Código de Processo Penal. Pelo parágrafo único, a lei alcança também o preso provisório e o condenado pela Justiça Eleitoral ou Militar recolhido a estabelecimento sujeito à jurisdição ordinária.$$),
(3,null,$$Direitos do condenado e do internado$$,$$Assegura ao condenado e ao internado todos os direitos não atingidos pela sentença ou pela lei. O parágrafo único veda distinção de natureza racial, social, religiosa ou política.$$),
(4,null,$$Cooperação da comunidade$$,$$Impõe ao Estado o dever de recorrer à cooperação da comunidade nas atividades de execução da pena e da medida de segurança.$$),
(5,null,$$Classificação dos condenados$$,$$Os condenados são classificados conforme antecedentes e personalidade, para orientar a individualização da execução penal.$$),
(6,null,$$Comissão Técnica de Classificação$$,$$A classificação é feita por Comissão Técnica de Classificação, que elabora o programa individualizador da pena privativa de liberdade adequada ao condenado ou ao preso provisório.$$),
(7,null,$$Composição da Comissão$$,$$A Comissão é presidida pelo Diretor e composta, no mínimo, por dois chefes de serviço, um psiquiatra, um psicólogo e um assistente social, quando se tratar de condenado à pena privativa de liberdade. Nos demais casos, o parágrafo único prevê atuação junto ao Juízo da Execução, com fiscais do Serviço Social.$$),
(8,null,$$Exame criminológico$$,$$O condenado em regime fechado é submetido a exame criminológico, para obter elementos de classificação e de individualização da execução. O parágrafo único admite o exame também para o condenado em regime semi-aberto.$$),
(9,null,$$Exame para dados da personalidade$$,$$Ao realizar o exame, a Comissão pode entrevistar pessoas (inciso I), requisitar dados e informações a repartições ou estabelecimentos privados (inciso II) e realizar outras diligências e exames necessários (inciso III), observando a ética profissional.$$),
(9,$$Art. 9-A$$,$$Identificação do perfil genético$$,$$Prevê a identificação do perfil genético, por extração de DNA, do condenado à pena de reclusão em regime inicial fechado, no ingresso no estabelecimento prisional. Os parágrafos tratam do banco de dados sigiloso (§ 1º), do acesso aos dados (§§ 2º e 3º), do descarte da amostra (§ 6º) e da recusa como falta grave (§ 8º).$$),
(10,null,$$Assistência ao preso e ao internado$$,$$A assistência é dever do Estado e visa prevenir o crime e orientar o retorno à convivência em sociedade. O parágrafo único a estende ao egresso.$$),
(11,null,$$Espécies de assistência$$,$$Enumera as espécies de assistência: material (inciso I), à saúde (inciso II), jurídica (inciso III), educacional (inciso IV), social (inciso V) e religiosa (inciso VI).$$),
(12,null,$$Assistência material$$,$$A assistência material consiste no fornecimento de alimentação, vestuário e instalações higiênicas ao preso e ao internado.$$),
(13,null,$$Instalações e serviços de uso pessoal$$,$$O estabelecimento deve ter instalações e serviços para as necessidades pessoais dos presos e locais para a venda de produtos e objetos permitidos e não fornecidos pela Administração.$$),
(14,null,$$Assistência à saúde$$,$$A assistência à saúde é preventiva e curativa e compreende atendimento médico, farmacêutico e odontológico. Se o estabelecimento não for aparelhado, a assistência é prestada em outro local, com autorização da direção (§ 2º). Os §§ 3º e 4º asseguram acompanhamento e tratamento humanitário à mulher, inclusive no pré-natal, no parto e no puerpério.$$),
(15,null,$$Assistência jurídica$$,$$A assistência jurídica é destinada aos presos e aos internados sem recursos financeiros para constituir advogado.$$),
(16,null,$$Assistência jurídica pela Defensoria Pública$$,$$As Unidades da Federação devem manter serviços de assistência jurídica integral e gratuita pela Defensoria Pública, dentro e fora dos estabelecimentos penais. Devem prestar auxílio estrutural, pessoal e material (§ 1º), prever local de atendimento nos estabelecimentos (§ 2º) e implementar Núcleos Especializados fora deles (§ 3º).$$)
) as v(n,t,c,a) where l.codigo='lep' and l.numero=v.n and l.titulo is not distinct from v.t and l.inciso is null and l.paragrafo is null and l.texto like 'Art%' and l.vigente;